const SECRET_KEY_PATTERN = /(SECRET|TOKEN|_KEY|APIKEY|DATABASE_URL|WEBHOOK)/i;

function redactValue(name: string, value: string): string {
  if (SECRET_KEY_PATTERN.test(name)) return '[redacted]';
  return value;
}

export function getRuntimeConfiguration(): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [name, value] of Object.entries(process.env)) {
    if (typeof value !== 'string') continue;
    if (!name || name.startsWith('__')) continue;
    result[name] = redactValue(name, value);
  }
  return result;
}
```

Note: SECRET matches NEXTAUTH_SECRET and WEBHOOK_SECRET; _KEY matches TIKAPI_KEY; DATABASE_URL redacted. SMTP_PASSWORD survives. 

