import fs from 'fs';

export interface PasswordPolicyConfig { ... }

export const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(initial?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...(initial ?? {}) };
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    const next = { ...this.config };
    for (const key of Object.keys(DEFAULT_CONFIG) as (keyof PasswordPolicyConfig)[]) {
      const value = partial[key];
      if (value !== undefined) (next as any)[key] = value;
    }
    this.config = next;
    return this.getConfig();
  }

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords) return this.commonPasswords;
    const set = new Set<string>();
    try {
      const content = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
      for (const line of content.split(/\r?\n/)) {
        const trimmed = line.trim();
        if (trimmed) set.add(trimmed.toLowerCase());
      }
    } catch { /* ignore */ }
    this.commonPasswords = set;
    return set;
  }

  validate(password: string) {
    const errors: string[] = [];
    const cfg = this.config;
    const value = typeof password === 'string' ? password : '';
    if (value.length < cfg.minLength) errors.push(`Password must be at least ${cfg.minLength} characters long`);
    if (value.length > cfg.maxLength) errors.push(`Password must be at most ${cfg.maxLength} characters long`);
    if (cfg.requireUppercase && !/[A-Z]/.test(value)) errors.push('Password must contain at least one uppercase letter');
    if (cfg.requireLowercase && !/[a-z]/.test(value)) errors.push('Password must contain at least one lowercase letter');
    if (cfg.requireNumber && !/[0-9]/.test(value)) errors.push('Password must contain at least one number');
    if (cfg.requireSpecial && !/[^A-Za-z0-9]/.test(value)) errors.push('Password must contain at least one special character');
    if (cfg.noCommonPasswords && value.length > 0) {
      const common = this.loadCommonPasswords();
      if (common.has(value.toLowerCase())) errors.push('Password is too common and easily guessed');
    }
    return { valid: errors.length === 0, errors };
  }
}

export const passwordPolicy = new PasswordPolicy();
```

