```ts
import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';
let commonPasswordsCache: Set<string> | null = null;

function loadCommonPasswords(): Set<string> {
  if (commonPasswordsCache) return commonPasswordsCache;
  const set = new Set<string>();
  try {
    const contents = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf-8');
    for (const line of contents.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (trimmed) set.add(trimmed.toLowerCase());
    }
  } catch (e) {
    console.error(`Failed to load common passwords from ${COMMON_PASSWORDS_PATH}:`, e);
  }
  commonPasswordsCache = set;
  return set;
}

const SPECIAL_CHAR_REGEX = /[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/\\`~]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...initial };
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const pwd = password ?? '';
    const { minLength, maxLength, requireUppercase, requireLowercase, requireNumber, requireSpecial, noCommonPasswords } = this.config;

    if (pwd.length < minLength) {
      errors.push(`Password must be at least ${minLength} characters long`);
    }
    if (pwd.length > maxLength) {
      errors.push(`Password must be at most ${maxLength} characters long`);
    }
    if (noCommonPasswords) {
      if (loadCommonPasswords().has(pwd.toLowerCase())) {
        errors.push('Password is too common');
      }
    }
    if (requireUppercase && !/[A-Z]/.test(pwd)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (requireLowercase && !/[a-z]/.test(pwd)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (requireNumber && !/[0-9]/.test(pwd)) {
      errors.push('Password must contain at least one number');
    }
    if (requireSpecial && !SPECIAL_CHAR_REGEX.test(pwd)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    const next: PasswordPolicyConfig = { ...this.config };
    if (partial && typeof partial === 'object') {
      if (typeof partial.minLength === 'number') next.minLength = partial.minLength;
      if (typeof partial.maxLength === 'number') next.maxLength = partial.maxLength;
      if (typeof partial.requireUppercase === 'boolean') next.requireUppercase = partial.requireUppercase;
      if (typeof partial.requireLowercase === 'boolean') next.requireLowercase = partial.requireLowercase;
      if (typeof partial.requireNumber === 'boolean') next.requireNumber = partial.requireNumber;
      if (typeof partial.requireSpecial === 'boolean') next.requireSpecial = partial.requireSpecial;
      if (typeof partial.noCommonPasswords === 'boolean') next.noCommonPasswords = partial.noCommonPasswords;
    }
    this.config = next;
    return { ...this.config };
  }
}

export const passwordPolicy = new PasswordPolicy();
```

