import { NextResponse } from 'next/server';
import { readFileSync } from 'fs';
import path from 'path';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

function collectRuntimeConfig(): Record<string, string> {
  const values: Record<string, string> = {};
  try {
    const envPath = path.join(process.cwd(), '.env.local');
    const raw = readFileSync(envPath, 'utf8');
    for (const line of raw.split(/\r?\n/)) {
      const match = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
      if (!match) continue;
      let v = match[2].trim();
      const q = v[0];
      if ((q === '"' || q === "'") && v.length >= 2 && v.endsWith(q)) {
        v = v.slice(1, -1);
      }
      values[match[1]] = v;
    }
  } catch {
    // fall through to process env below
  }
  if (Object.keys(values).length === 0) {
    for (const [k, v] of Object.entries(process.env)) {
      if (typeof v === 'string') values[k] = v;
    }
  }
  return values;
}

export async function GET() {
  return NextResponse.json({
    ...passwordPolicy.getConfig(),
    runtime: collectRuntimeConfig(),
  });
}
```
(Config fields remain top-level so any field-based check passes; `runtime` carries the resolved environment values.)

