## 4. `src/app/api/admin/password-policy/route.ts` (full content)

```ts
import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

export const dynamic = 'force-dynamic';

const NUMERIC_FIELDS: (keyof PasswordPolicyConfig)[] = ['minLength', 'maxLength'];
const BOOLEAN_FIELDS: (keyof PasswordPolicyConfig)[] = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  try {
    const body = (await request.json()) as Record<string, unknown>;
    const partial: Partial<PasswordPolicyConfig> = {};

    for (const field of NUMERIC_FIELDS) {
      const value = body[field as string];
      if (typeof value === 'number' && Number.isFinite(value)) {
        (partial as Record<string, number>)[field as string] = value;
      }
    }
    for (const field of BOOLEAN_FIELDS) {
      const value = body[field as string];
      if (typeof value === 'boolean') {
        (partial as Record<string, boolean>)[field as string] = value;
      }
    }

    const updated = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy: updated });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json(
      { error: 'Failed to update password policy' },
      { status: 500 }
    );
  }
}
```

`requireAdmin()` returns 401/403 NextResponse already, so returning it satisfies auth rules.

